<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { api, session, errorText } from '../../../frontend/src/api';
import type { AdminUser } from '../../../packages/contracts/src/index.js';
import ModalSheet from '../../../frontend/src/components/ModalSheet.vue';
const loading = ref(true), busy = ref(false), error = ref(''), users = ref<AdminUser[]>([]), cursor = ref<string | null>(null), notice = ref('');
const modal = ref<'create' | 'edit' | 'password' | null>(null), target = ref<AdminUser | null>(null), modalError = ref('');
const form = reactive({ username: '', displayName: '', password: '', role: 'editor', active: true });
const emit = defineEmits<{ changed: [] }>();
async function load(more = false) { const page = await api<{ items: AdminUser[]; nextCursor: string | null }>('/admin/users' + (more && cursor.value ? '?cursor=' + encodeURIComponent(cursor.value) : '')); users.value = more ? [...users.value, ...page.items] : page.items; cursor.value = page.nextCursor; }
onMounted(refresh);
function show(kind: typeof modal.value, user: AdminUser | null = null) { target.value = user; modal.value = kind; modalError.value = ''; Object.assign(form, { username: user?.username ?? '', displayName: user?.displayName ?? '', password: '', role: user?.role ?? 'editor', active: user?.active ?? true }); }
function close() { if (busy.value) return; const changed = !!form.password || (modal.value === 'create' ? !!(form.username || form.displayName) : modal.value === 'edit' && !!target.value && (form.displayName !== target.value.displayName || form.role !== target.value.role || form.active !== target.value.active)); if (changed && !window.confirm('放弃尚未保存的账号设置？')) return; modal.value = null; form.password = ''; }
async function save() {
  if (busy.value) return; busy.value = true; modalError.value = ''; const kind = modal.value;
  try {
    if (kind === 'create') await api('/admin/users', 'POST', { username: form.username, displayName: form.displayName, password: form.password, role: form.role });
    else if (kind === 'edit') await api('/admin/users/' + target.value!.id, 'PATCH', { baseVersion: target.value!.version, displayName: form.displayName, role: form.role, active: form.active });
    else await api('/admin/users/' + target.value!.id + '/password', 'POST', { baseVersion: target.value!.version, password: form.password });
    form.password = ''; modal.value = null; notice.value = kind === 'password' ? '密码已重置，该账号的已有登录会话已撤销。' : '账号设置已保存。';
    if (kind === 'password' && target.value!.id === session.value?.user.id) session.value = null; else await load(); emit('changed');
  } catch (e) { modalError.value = errorText(e); } finally { busy.value = false; }
}
async function moreUsers() { busy.value = true; error.value = ''; try { await load(true); } catch(e) { error.value = errorText(e); } finally { busy.value = false; } }
async function refresh() { error.value = ''; busy.value = true; try { await load(); } catch (e) { error.value = errorText(e); } finally { busy.value = false; loading.value = false; } }
</script>
<template><p v-if="error" class="flow-form-errors" role="alert">{{ error }}<button class="text-button" @click="refresh">重试</button></p><p v-if="notice" class="admin-notice" role="status">{{ notice }}</p><p v-if="loading" class="admin-message">正在读取账号…</p><section class="admin-section"><div class="admin-section-top"><div><h2>账号管理</h2><p>停用、变更角色或重置密码后，原有登录会话会撤销。</p></div><div class="account-toolbar"><button class="secondary-button" :disabled="busy" @click="refresh">刷新账号</button><button class="primary compact" :disabled="busy" @click="show('create')">创建账号</button></div></div><div class="admin-users"><article v-for="user in users" :key="user.id" class="admin-user"><div class="od-fill"><h3>{{ user.displayName }}</h3><p>{{ user.username }} · {{ user.role === 'owner' ? '管理员' : '普通编辑' }} · {{ user.active ? '已启用' : '已停用' }}</p><small>{{ new Date(user.createdAt).toLocaleDateString('zh-CN') }} 创建</small></div><div class="admin-user-actions"><button class="secondary-button" :disabled="busy" @click="show('edit', user)">编辑账号</button><button class="text-button" :disabled="busy" @click="show('password', user)">重置密码</button></div></article></div><button v-if="cursor" class="secondary-button full" :disabled="busy" @click="moreUsers">加载更多账号</button></section><ModalSheet v-if="modal" :title="modal === 'create' ? '创建账号' : modal === 'edit' ? '编辑账号' : '重置账号密码'" :busy="busy" @close="close"><form id="admin-user-form" @submit.prevent="save"><p v-if="target" class="modal-target">{{ target.username }}</p><div v-if="modal === 'create'" class="flow-field"><label for="new-username">登录账号</label><input id="new-username" v-model="form.username" required pattern="[a-zA-Z0-9_.-]{1,64}" maxlength="64" autocomplete="off"><small>字母、数字、下划线、点或连字符。</small></div><template v-if="modal !== 'password'"><div class="flow-field"><label for="new-display">显示名称</label><input id="new-display" v-model="form.displayName" required maxlength="80"></div><div class="flow-field"><label for="new-role">角色</label><select id="new-role" v-model="form.role"><option value="editor">普通编辑</option><option value="owner">管理员</option></select></div><label v-if="modal === 'edit'" class="admin-check"><input v-model="form.active" type="checkbox">启用此账号</label></template><div v-if="modal !== 'edit'" class="flow-field"><label for="new-password">{{ modal === 'create' ? '初始密码' : '新密码' }}</label><input id="new-password" v-model="form.password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"><small>至少 12 个字符；密码不会保存在前端草稿中。</small></div><p v-if="modal === 'password'" class="confirm-copy">保存后将撤销该账号全部登录会话，需要使用新密码重新登录。</p><p v-if="modalError" class="flow-form-errors" role="alert">{{ modalError }}</p></form><template #footer><button class="primary" type="submit" form="admin-user-form" :disabled="busy">{{ busy ? '正在保存…' : '确认保存' }}</button></template></ModalSheet></template>
